rules:
  - id: parameterized-sql-only-typescript
    languages: [typescript]
    severity: ERROR
    message: SQL must be built with query parameters or an ORM, not by concatenating or interpolating values into the query string.
    metadata:
      category: security
    patterns:
      - pattern-either:
          - pattern: $DB.$M($A + $B, ...)
          - pattern: $DB.$M(util.format(...), ...)
          - patterns:
              - pattern-inside: $DB.$M(...)
              - pattern-regex: '`[^`]*\$\{'
      - metavariable-regex:
          metavariable: $M
          regex: ^(query|execute|exec|raw|run|all|get|prepare)$
