import util from "util";
import { Pool } from "pg";

const TABLE = "users";
const pool = new Pool();
const repo = { find: (_q: unknown) => Promise.resolve([]) };

export async function unsafeById(id: string) {
  // ruleid: parameterized-sql-only-typescript
  await pool.query("SELECT * FROM users WHERE id = " + id);
  // ruleid: parameterized-sql-only-typescript
  const r = await pool.query(`SELECT * FROM ${TABLE} WHERE id = '${id}'`);
  return r.rows;
}

export function unsafeByName(name: string) {
  // ruleid: parameterized-sql-only-typescript
  return pool.query(util.format("SELECT * FROM users WHERE name = '%s'", name));
}

class UserStore {
  constructor(private db: Pool) {}

  remove(id: string) {
    // ruleid: parameterized-sql-only-typescript
    return this.db.query("DELETE FROM users WHERE id = " + id);
  }
}

export async function safeById(id: string) {
  // ok: parameterized-sql-only-typescript
  const r = await pool.query("SELECT * FROM users WHERE id = $1", [id]);
  return r.rows;
}

export async function safeFind(id: string) {
  // ok: parameterized-sql-only-typescript
  return repo.find({ where: { id } });
}

export async function safePlaceholder(id: string) {
